def convert_from_base(cents: int, rate: Decimal) -> int:
    """Convert base cents to a currency worth `rate` base: amount / rate, rounded to the cent.

    Halves round away from zero, so a credit and the matching debt stay the same size.
    """
    num, den = rate.as_integer_ratio()
    sign = -1 if cents < 0 else 1
    return sign * ((2 * abs(cents) * den + num) // (2 * num))
